package com.bank.flink.delivery;

// A card-delivery scan event (Kafka key = userId, so partitioned by user).
class DeliveryEvent {
    enum Status { PICKED_UP, IN_TRANSIT, OUT_FOR_DELIVERY, DELIVERED }

    private final String userId;
    private final Status status;
    private final long eventTimeMillis;
    private String region; // filled by enrichment

    DeliveryEvent(String userId, Status status, long eventTimeMillis) {
        this.userId = userId;
        this.status = status;
        this.eventTimeMillis = eventTimeMillis;
    }

    String getUserId() { return userId; }
    Status getStatus() { return status; }
    long getEventTimeMillis() { return eventTimeMillis; }
    String getRegion() { return region; }
    void setRegion(String region) { this.region = region; }
}
