package com.bank.flink.delivery;

import java.util.logging.Logger;

// The forwarding map: stateless enrichment, preserves partitioning (no shuffle).
class Enricher {
    private static final Logger log = Logger.getLogger(Enricher.class.getName());

    DeliveryEvent enrich(DeliveryEvent e) {
        // e.g. derive region from userId prefix (SAV=north, CUR=west).
        e.setRegion(e.getUserId().startsWith("SAV") ? "NORTH" : "WEST");
        log.fine(() -> "enriched " + e.getUserId() + " region=" + e.getRegion());
        return e;
    }
}
