package com.bank.flink.delivery;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.logging.Logger;

// keyBy(userId) + 30-min tumbling window aggregation (per-user stats).
// Models the redistributing (shuffle) exchange + keyed window state.
class KeyedWindowAggregator {
    private static final Logger log = Logger.getLogger(KeyedWindowAggregator.class.getName());
    private final long windowSizeMs;

    // keyed window state: (userId, windowStart) -> [totalScans, completed]
    private final Map<String, int[]> windowState = new HashMap<>();

    KeyedWindowAggregator(long windowSizeMs) { this.windowSizeMs = windowSizeMs; }

    private long windowStart(long ts) { return (ts / windowSizeMs) * windowSizeMs; }
    private String keyOf(String userId, long ws) { return userId + "@" + ws; }

    // keyBy routes by userId; here we add to that user's current window bucket.
    void process(DeliveryEvent e) {
        long ws = windowStart(e.getEventTimeMillis());
        String key = keyOf(e.getUserId(), ws);
        int[] agg = windowState.computeIfAbsent(key, k -> new int[2]);
        agg[0]++; // total scans
        if (e.getStatus() == DeliveryEvent.Status.DELIVERED) agg[1]++;
        log.fine(() -> "window " + key + " total=" + agg[0] + " completed=" + agg[1]);
    }

    // Watermark passes window end: fire all windows ending at/before it.
    List<String> fireClosedWindows(long watermark) {
        List<String> results = new ArrayList<>();
        List<String> toRemove = new ArrayList<>();
        for (Map.Entry<String, int[]> en : windowState.entrySet()) {
            long ws = Long.parseLong(en.getKey().split("@")[1]);
            if (watermark >= ws + windowSizeMs) {
                int[] agg = en.getValue();
                String row = "UPSERT delivery_stats " + en.getKey()
                        + " total=" + agg[0] + " completed=" + agg[1];
                results.add(row);
                toRemove.add(en.getKey());
                log.info(() -> row);
            }
        }
        toRemove.forEach(windowState::remove);
        return results;
    }

    Map<String, int[]> snapshotState() { return new HashMap<>(windowState); }
    void restoreState(Map<String, int[]> s) { windowState.clear(); windowState.putAll(s); }
}
