package com.bank.flink.delivery;

import java.util.HashMap;
import java.util.Map;
import java.util.logging.Logger;

// Drives the pipeline with periodic checkpoints and a crash/replay to show
// exactly-once: window state + source offset are snapshotted together.
class CheckpointedRunner {
    private static final Logger log = Logger.getLogger(CheckpointedRunner.class.getName());

    private final Enricher enricher;
    private final KeyedWindowAggregator aggregator;

    private Map<String, int[]> checkpointedState = new HashMap<>();
    private long checkpointedOffset = -1;
    private long currentOffset = -1;

    CheckpointedRunner(Enricher enricher, KeyedWindowAggregator aggregator) {
        this.enricher = enricher;
        this.aggregator = aggregator;
    }

    void ingest(DeliveryEvent e, long offset) {
        aggregator.process(enricher.enrich(e)); // forwarding map then keyed window
        currentOffset = offset;
    }

    void checkpoint() {
        checkpointedState = aggregator.snapshotState();
        checkpointedOffset = currentOffset;
        log.info(() -> "CHECKPOINT offset=" + checkpointedOffset
                + " windows=" + checkpointedState.size());
    }

    long restore() {
        aggregator.restoreState(checkpointedState);
        currentOffset = checkpointedOffset;
        log.warning(() -> "RESTORE offset=" + checkpointedOffset);
        return checkpointedOffset + 1; // replay from next offset
    }
}
