package com.bank.flink.delivery;

import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class DeliveryPipelineDemo {
    private static final Logger log = Logger.getLogger(DeliveryPipelineDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        root.addHandler(handler);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        long min = 60L * 1000;
        Enricher enricher = new Enricher();
        KeyedWindowAggregator aggregator = new KeyedWindowAggregator(30 * min);
        CheckpointedRunner runner = new CheckpointedRunner(enricher, aggregator);

        // Window [0,30m): SAV2001 three scans (one delivered); CUR3001 two scans.
        runner.ingest(new DeliveryEvent("SAV2001", DeliveryEvent.Status.PICKED_UP, 2 * min), 1);
        runner.ingest(new DeliveryEvent("SAV2001", DeliveryEvent.Status.IN_TRANSIT, 10 * min), 2);
        runner.ingest(new DeliveryEvent("CUR3001", DeliveryEvent.Status.PICKED_UP, 12 * min), 3);
        runner.checkpoint(); // offset 3, window state saved

        runner.ingest(new DeliveryEvent("SAV2001", DeliveryEvent.Status.DELIVERED, 20 * min), 4);
        runner.ingest(new DeliveryEvent("CUR3001", DeliveryEvent.Status.IN_TRANSIT, 25 * min), 5);

        // Crash before next checkpoint: offsets 4 and 5 not yet checkpointed.
        long resumeOffset = runner.restore(); // state rewinds to offset 3
        log.info("replay from offset " + resumeOffset);

        // Replay offsets 4 and 5 (Kafka re-reads them) -> counted exactly once.
        runner.ingest(new DeliveryEvent("SAV2001", DeliveryEvent.Status.DELIVERED, 20 * min), 4);
        runner.ingest(new DeliveryEvent("CUR3001", DeliveryEvent.Status.IN_TRANSIT, 25 * min), 5);

        // Watermark passes 30m: fire the window.
        aggregator.fireClosedWindows(31 * min);
    }
}

